{
  "findings": [
    {
      "check_id": "CKV_GCP_18",
      "title": "GKE cluster has legacy ABAC enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "Legacy ABAC can be used to grant broad, ungranular permissions to cluster nodes, potentially leading to over-privileged access"
    },
    {
      "check_id": "CKV_GCP_21",
      "title": "GKE cluster has client certificate issued",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Issuing client certificates can lead to unmanaged authentication and authorization"
    },
    {
      "check_id": "CKV_GCP_7",
      "title": "GKE cluster has alpha features enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "Alpha features are not stable and may have security vulnerabilities or unexpected behavior"
    },
    {
      "check_id": "CKV_GCP_12",
      "title": "GKE cluster's node config has too broad OAuth scopes",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The 'compute' OAuth scope is too broad and may grant unnecessary permissions to nodes"
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name               = \"${var.vault_user}-k8s-cluster\"\n  description        = \"example k8s cluster\"\n  zone               = \"${var.gcp_zone}\"\n  initial_node_count = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha = \"false\"\n  enable_legacy_abac = \"false\"\n  master_auth {\n    username = \"${var.master_username}\"\n    password = \"${var.master_password}\"\n    client_certificate_config {\n      issue_client_certificate = false\n    }\n  }\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n}",
  "fix_summary": "Disabled legacy ABAC, alpha features, and client certificate issuance. Removed the 'compute' OAuth scope from node config to limit permissions"
}
